def predict(board, action):
    mouse_action, row, col = action
    row, col = int(row), int(col)
    old_cell = board[row][col]

    if old_cell == 'W':
        new_cell = 'O'
    elif old_cell == 'O':
        new_cell = 'W'
    else:
        raise ValueError("Old cell must be 'W' or 'O'")

    # Create a copy of the board
    new_board = [list(row) for row in board]

    # Find all cells in the 8-connected neighborhood of the mouse action
    for r in range(max(0, row-1), min(64, row+2)):
        for c in range(max(0, col-1), min(64, col+2)):
            if (r, c) != (row, col):
                if new_board[r][c] == 'W':
                    new_board[r][c] = 'O' if new_cell == 'W' else 'W'

    # Update the mouse action cell
    new_board[row][col] = new_cell

    return [''.join(row) for row in new_board]
